"Autoriser la localisation":"Standort erlauben",
"Cette autorisation permet à l'application d'utiliser la position GPS de votre appareil pour afficher votre position, activer le partage de localisation et les fonctions de sécurité que vous choisissez. Rien n'est partagé sans votre action.":"Mit dieser Berechtigung darf die App die GPS-Position deines Geräts nutzen, um deinen Standort anzuzeigen sowie die Standortfreigabe und die von dir gewählten Sicherheitsfunktionen zu aktivieren. Ohne deine Aktion wird nichts geteilt.",
"Localisation désactivée":"Standort deaktiviert",
"Recherche de la position…":"Position wird gesucht…",
"Permission refusée":"Berechtigung verweigert",
"Position indisponible":"Position nicht verfügbar",
"Délai dépassé":"Zeitüberschreitung",
"Navigateur incompatible":"Browser nicht kompatibel",
"Connexion non sécurisée":"Unsichere Verbindung",
"La localisation est refusée ou bloquée pour cette application. Autorise-la dans les réglages du navigateur (cadenas ▸ Autorisations ▸ Position), puis réessaie. L'application reste utilisable sans.":"Der Standortzugriff wurde für diese App abgelehnt oder blockiert. Erlaube ihn in den Browsereinstellungen (Schloss ▸ Berechtigungen ▸ Standort) und versuche es dann erneut. Die App bleibt auch ohne nutzbar.",
"Ton appareil n'arrive pas à déterminer sa position. Vérifie que le GPS est activé et que tu as du réseau, puis réessaie.":"Dein Gerät kann seine Position nicht bestimmen. Prüfe, ob GPS aktiviert ist und du Netz hast, und versuche es dann erneut.",
"La position met trop de temps à arriver. Essaie à l'extérieur ou près d'une fenêtre.":"Die Position braucht zu lange. Versuche es draußen oder in der Nähe eines Fensters.",
"Ce navigateur ne gère pas la géolocalisation. Essaie Chrome, Safari ou Firefox à jour.":"Dieser Browser unterstützt keine Geolokalisierung. Probiere eine aktuelle Version von Chrome, Safari oder Firefox.",
"La géolocalisation exige une connexion sécurisée (HTTPS).":"Die Geolokalisierung erfordert eine sichere Verbindung (HTTPS).",
"Une erreur est survenue. Réessaie.":"Ein Fehler ist aufgetreten. Versuche es erneut.",
"Action refusée : les règles Firestore du Centre de localisation ne sont pas encore publiées (ou pas à jour). Va dans la section « Vérifier ma configuration » (onglet Confidentialité).":"Aktion abgelehnt: Die Firestore-Regeln des Standortzentrums sind noch nicht veröffentlicht (oder nicht aktuell). Gehe zum Bereich „Meine Konfiguration prüfen“ (Tab Datenschutz).",
"Index Firestore manquant : voir la console du navigateur.":"Firestore-Index fehlt: siehe Browser-Konsole.",
