"Suivre cet appareil":"Dieses Gerät verfolgen",
"Met à jour la dernière position de cet appareil quand l'application est ouverte, pour pouvoir le retrouver plus tard.":"Aktualisiert die letzte Position dieses Geräts, wenn die App geöffnet ist, damit du es später wiederfinden kannst.",
"Demander une actualisation":"Aktualisierung anfordern",
"Demande envoyée. Elle n'aboutit que si l'appareil a l'application ouverte avec le suivi activé.":"Anfrage gesendet. Sie funktioniert nur, wenn die App auf dem Gerät geöffnet und die Verfolgung aktiviert ist.",
"Voir sur la carte":"Auf Karte ansehen",
"Aucun appareil enregistré. Active « Suivre cet appareil » sur chacun de tes appareils.":"Kein Gerät registriert. Aktiviere „Dieses Gerät verfolgen“ auf jedem deiner Geräte.",
"Limite technique : un navigateur ne peut pas être réveillé à distance. La dernière position affichée est celle reçue quand l'application était ouverte.":"Technische Einschränkung: Ein Browser kann nicht aus der Ferne aufgeweckt werden. Angezeigt wird die zuletzt empfangene Position, als die App geöffnet war.",
"Aucune position reçue.":"Keine Position empfangen.",
"Nom de l'appareil":"Gerätename",
