"Historique de mes positions":"Verlauf meiner Positionen",
"L'historique est désactivé. Tu peux l'activer dans Confidentialité.":"Der Verlauf ist deaktiviert. Du kannst ihn unter Datenschutz aktivieren.",
"Aucune position enregistrée.":"Keine Position gespeichert.",
"Effacer mon historique":"Meinen Verlauf löschen",
"Historique effacé.":"Verlauf gelöscht.",
"Une position toutes les {n} min au plus, seulement si tu as bougé d'au moins {m} m. Supprimée après {d} jours.":"Höchstens eine Position alle {n} Min., nur wenn du dich mindestens {m} m bewegt hast. Wird nach {d} Tagen gelöscht.",
"Ce qui est collecté et pourquoi":"Was erfasst wird und warum",
"Ta position GPS : uniquement pour l'afficher sur la carte quand ce centre est ouvert. Rien n'est envoyé à nos serveurs tant que tu ne partages pas, n'actives pas le SOS, le suivi d'appareil ou l'historique.":"Deine GPS-Position: nur zur Anzeige auf der Karte, wenn dieses Zentrum geöffnet ist. Es wird nichts an unsere Server gesendet, solange du nichts teilst und weder SOS, Gerätetracking noch Verlauf aktivierst.",
"Partage : ta dernière position est visible uniquement par les personnes que tu choisis, pendant la durée choisie. Tu peux arrêter à tout moment.":"Freigabe: Deine letzte Position ist nur für die von dir gewählten Personen sichtbar, für die gewählte Dauer. Du kannst jederzeit beenden.",
"SOS : position et heure partagées avec tes contacts d'urgence qui ont accepté, tant que le SOS est actif.":"SOS: Position und Uhrzeit werden mit deinen Notfallkontakten geteilt, die zugestimmt haben, solange SOS aktiv ist.",
"Appareil : dernière position, heure et niveau de batterie (si disponible), visibles par toi seul.":"Gerät: letzte Position, Uhrzeit und Akkustand (falls verfügbar), nur für dich sichtbar.",
"Historique : désactivé par défaut, visible par toi seul, positions espacées et supprimées automatiquement.":"Verlauf: standardmäßig deaktiviert, nur für dich sichtbar, Positionen in Abständen und automatisch gelöscht.",
"Adresse et carte : les coordonnées sont envoyées à OpenStreetMap (Nominatim) pour afficher l'adresse, et le fond de carte vient d'OpenStreetMap.":"Adresse und Karte: Die Koordinaten werden an OpenStreetMap (Nominatim) gesendet, um die Adresse anzuzeigen, und der Kartenhintergrund stammt von OpenStreetMap.",
