"Supprimer toutes mes données de localisation":"Alle meine Standortdaten löschen",
"Supprimer définitivement ton historique, tes appareils, tes partages, tes contacts d'urgence et ta session SOS ?":"Deinen Verlauf, deine Geräte, deine Freigaben, deine Notfallkontakte und deine SOS-Sitzung endgültig löschen?",
"Données de localisation supprimées.":"Standortdaten gelöscht.",
"La carte n'a pas pu se charger (réseau ?). Voici tes coordonnées :":"Die Karte konnte nicht geladen werden (Netzwerk?). Hier sind deine Koordinaten:",
