"Pour retrouver tes proches en un clic (et qu'ils te retrouvent), enregistre ton numéro ou ton email. Ils ne sont jamais affichés : ils servent seulement à te retrouver quand quelqu'un les tape.":"Damit du deine Liebsten mit einem Klick findest (und sie dich), speichere deine Nummer oder deine E-Mail. Sie werden nie angezeigt: Sie dienen nur dazu, dich zu finden, wenn jemand sie eingibt.",
"Cherche un proche par nom, email ou numéro":"Suche eine nahestehende Person nach Name, E-Mail oder Nummer",
"Touche « Localiser » : il reçoit ta demande":"Tippe auf „Orten“: Die Person erhält deine Anfrage",
"Il accepte (ou supprime) et choisit la durée":"Sie nimmt an (oder löscht) und wählt die Dauer",
"Renseigne au moins un numéro ou un email valide.":"Gib mindestens eine gültige Nummer oder E-Mail an.",
"J'accepte d'apparaître dans l'annuaire (nom + photo). Personne ne voit ma position sans mon accord.":"Ich stimme zu, im Verzeichnis zu erscheinen (Name + Foto). Niemand sieht meinen Standort ohne meine Zustimmung.",
"Coche la case pour continuer.":"Setze das Häkchen, um fortzufahren.",
