"Pendant combien de temps {name} peut-il voir ta position ? Tu pourras arrêter à tout moment.":"Wie lange darf {name} deinen Standort sehen? Du kannst jederzeit beenden.",
"Annuler la demande":"Anfrage abbrechen",
