"Tu ne seras plus retrouvable par nom, email ou numéro. Tes partages en cours ne sont pas modifiés.":"Du kannst nicht mehr per Name, E-Mail oder Nummer gefunden werden. Deine laufenden Freigaben bleiben unverändert.",
"Tu as quitté l'annuaire.":"Du hast das Verzeichnis verlassen.",
"Annuaire : seuls ton nom, ta photo et ton @utilisateur sont visibles par les membres inscrits. Ton email et ton numéro ne sont jamais affichés ; seule une empreinte chiffrée sert à te retrouver.":"Verzeichnis: Nur dein Name, dein Foto und dein @Benutzername sind für registrierte Mitglieder sichtbar. Deine E-Mail und deine Nummer werden nie angezeigt; nur ein verschlüsselter Fingerabdruck dient dazu, dich zu finden.",
"Rejoins l'annuaire pour partager ta position en un clic avec tes proches.":"Tritt dem Verzeichnis bei, um deinen Standort mit einem Klick mit deinen Liebsten zu teilen.",
