"Contact d'urgence accepté":"Notfallkontakt akzeptiert",
"{name} a accepté d'être ton contact d'urgence.":"{name} hat zugestimmt, dein Notfallkontakt zu sein.",
"Et quand l'application est fermée ?":"Und wenn die App geschlossen ist?",
"Bloquée par le site":"Von der Website blockiert",
"La localisation est bloquée par la configuration du site. Si tu administres le site, vérifie que vercel.json (Permissions-Policy : geolocation=(self)) est bien déployé.":"Der Standortzugriff ist durch die Konfiguration der Website blockiert. Wenn du die Website verwaltest, prüfe, ob vercel.json (Permissions-Policy: geolocation=(self)) korrekt bereitgestellt ist.",
"La carte est bloquée par la configuration de sécurité du site. Si tu administres le site, vérifie que vercel.json est bien déployé.":"Die Karte ist durch die Sicherheitskonfiguration der Website blockiert. Wenn du die Website verwaltest, prüfe, ob vercel.json korrekt bereitgestellt ist.",
"Mon lien de localisation":"Mein Standortlink",
"Crée un lien et envoie-le sur WhatsApp, Messenger, Facebook, TikTok, Instagram… La personne qui l'ouvre se connecte à Coeurnoh Universe, puis voit ta position sur la carte.":"Erstelle einen Link und sende ihn über WhatsApp, Messenger, Facebook, TikTok, Instagram… Die Person, die ihn öffnet, meldet sich bei Coeurnoh Universe an und sieht dann deinen Standort auf der Karte.",
"Toute personne qui ouvre ce lien et se connecte verra ta position jusqu'à l'expiration. Tu peux le désactiver à tout moment.":"Jede Person, die diesen Link öffnet und sich anmeldet, sieht deinen Standort bis zum Ablauf. Du kannst ihn jederzeit deaktivieren.",
"Créer mon lien":"Meinen Link erstellen",
"Lien créé. Choisis comment l'envoyer.":"Link erstellt. Wähle, wie du ihn sendest.",
"Mes liens actifs":"Meine aktiven Links",
"Jusqu'à désactivation":"Bis zur Deaktivierung",
"{n} connectée(s)":"{n} angemeldet",
"Lien copié.":"Link kopiert.",
"Lien désactivé.":"Link deaktiviert.",
"Envoyer par":"Senden über",
"Autres apps":"Andere Apps",
"TikTok / Instagram : touche « Autres apps » ou copie le lien, puis colle-le dans ton message ou ta bio.":"TikTok / Instagram: Tippe auf „Andere Apps“ oder kopiere den Link und füge ihn in deine Nachricht oder Bio ein.",
"{name} partage sa position avec toi sur Coeurnoh Universe. Ouvre le lien et connecte-toi pour la voir :":"{name} teilt seinen Standort mit dir auf Coeurnoh Universe. Öffne den Link und melde dich an, um ihn zu sehen:",
"{name} partage sa position avec toi":"{name} teilt seinen Standort mit dir",
"Tu verras sa position sur la carte jusqu'à {until}. Tu pourras quitter à tout moment.":"Du siehst den Standort auf der Karte bis {until}. Du kannst jederzeit aussteigen.",
"Voir sa position":"Standort ansehen",
"Position partagée avec toi.":"Standort mit dir geteilt.",
"Lien invalide ou désactivé.":"Link ungültig oder deaktiviert.",
"Ce lien a expiré.":"Dieser Link ist abgelaufen.",
"C'est ton propre lien.":"Das ist dein eigener Link.",
"Lien ouvert":"Link geöffnet",
"{name} a ouvert ton lien et voit ta position.":"{name} hat deinen Link geöffnet und sieht deinen Standort.",
"Plein écran":"Vollbild",
"Quitter le plein écran":"Vollbild beenden",
"L'annuaire est inaccessible. Les règles Firestore du Centre de localisation ne sont probablement pas encore publiées. Ouvre « Vérifier ma configuration » (onglet Confidentialité).":"Das Verzeichnis ist nicht erreichbar. Die Firestore-Regeln des Standortzentrums sind wahrscheinlich noch nicht veröffentlicht. Öffne „Meine Konfiguration prüfen“ (Tab Datenschutz).",
"Tu es l'un des premiers membres ! Invite tes proches, ou crée ton lien de localisation juste en dessous.":"Du bist eines der ersten Mitglieder! Lade deine Liebsten ein oder erstelle direkt darunter deinen Standortlink.",
"Vérifier ma configuration":"Meine Konfiguration prüfen",
"Lancer la vérification":"Prüfung starten",
"Réparer et recharger l'application":"Reparieren und App neu laden",
"Connexion sécurisée (HTTPS)":"Sichere Verbindung (HTTPS)",
"Configuration du serveur (vercel.json)":"Serverkonfiguration (vercel.json)",
"Autorisation GPS du site":"GPS-Berechtigung der Website",
"Permission GPS du téléphone":"GPS-Berechtigung des Telefons",
"Règles Firestore":"Firestore-Regeln",
"Le serveur envoie encore l'ancienne configuration : le fichier vercel.json n'est pas déployé (GitHub → Vercel, attends le statut « Ready »).":"Der Server sendet noch die alte Konfiguration: Die Datei vercel.json ist nicht bereitgestellt (GitHub → Vercel, warte auf den Status „Ready“).",
"Le serveur est à jour mais cet appareil garde une ancienne version : touche « Réparer et recharger ».":"Der Server ist aktuell, aber dieses Gerät hat noch eine alte Version: Tippe auf „Reparieren und neu laden“.",
"Règles non publiées ou incomplètes : Firebase Console ▸ Firestore ▸ Règles ▸ coller le fichier complet ▸ Publier.":"Regeln nicht veröffentlicht oder unvollständig: Firebase Console ▸ Firestore ▸ Regeln ▸ vollständige Datei einfügen ▸ Veröffentlichen.",
"Impossible de charger la carte (réseau ou blocage).":"Karte kann nicht geladen werden (Netzwerk oder Blockierung).",
"Pas encore demandée : touche « Activer ma position » dans l'onglet Position.":"Noch nicht angefragt: Tippe im Tab Position auf „Meinen Standort aktivieren“.",
"Notifications bloquées : autorise-les dans les réglages du navigateur pour recevoir les alertes.":"Benachrichtigungen blockiert: Erlaube sie in den Browsereinstellungen, um Alarme zu erhalten.",
"Pas encore autorisées : active-les pour recevoir les alertes même application fermée.":"Noch nicht erlaubt: Aktiviere sie, um Alarme auch bei geschlossener App zu erhalten.",
"Mise à jour de l'application…":"App wird aktualisiert…",
"Dépend de l'étape « Autorisation GPS du site » : corrige-la d'abord (bouton Réparer), puis relance la vérification.":"Hängt vom Schritt „GPS-Berechtigung der Website“ ab: Behebe ihn zuerst (Button Reparieren) und starte dann die Prüfung neu.",
"Échange mutuel : partager aussi ma position":"Gegenseitiger Austausch: auch meinen Standort teilen",
"Quand je touche « Localiser », je partage aussi ma position avec cette personne (durée au choix) : vous vous voyez chacun sur la carte.":"Wenn ich auf „Orten“ tippe, teile ich auch meinen Standort mit dieser Person (Dauer nach Wahl): Ihr seht euch gegenseitig auf der Karte.",
"Échanger nos positions avec {name}":"Standorte mit {name} austauschen",
"Tu envoies une demande à {name} ET tu partages ta position avec elle/lui pendant la durée choisie. Dès qu'elle/il accepte, vous vous voyez mutuellement.":"Du sendest {name} eine Anfrage UND teilst deinen Standort für die gewählte Dauer mit dieser Person. Sobald sie zustimmt, seht ihr euch gegenseitig.",
"Demande envoyée et position partagée.":"Anfrage gesendet und Standort geteilt.",
"Enregistre ton numéro ou ton email pour apparaître dans la liste et être retrouvé. Tu peux déjà chercher et envoyer des demandes ci-dessous.":"Speichere deine Nummer oder E-Mail, um in der Liste zu erscheinen und gefunden zu werden. Du kannst unten schon suchen und Anfragen senden.",
