"Autre montant":"Anderer Betrag",
"Tu es envoyé directement vers la page de paiement sécurisée pour choisir ton réseau. Ton solde est crédité automatiquement dès que le paiement est confirmé.":"Du wirst direkt zur sicheren Zahlungsseite weitergeleitet, um dein Netzwerk zu wählen. Dein Guthaben wird automatisch aufgeladen, sobald die Zahlung bestätigt ist.",
"Paiement sécurisé : ton solde n’est crédité qu’après confirmation automatique du paiement.":"Sichere Zahlung: Dein Guthaben wird erst nach der automatischen Zahlungsbestätigung aufgeladen.",
"Indique le montant (minimum 2 $) puis appuie sur « Payer » : tu es redirigé vers la page de paiement crypto sécurisée.":"Gib den Betrag an (mindestens 2 $) und tippe auf „Zahlen“: Du wirst zur sicheren Krypto-Zahlungsseite weitergeleitet.",
"Choisis ta crypto (USDT recommandé) et envoie le montant exact à l’adresse affichée.":"Wähle deine Kryptowährung (USDT empfohlen) und sende den genauen Betrag an die angezeigte Adresse.",
