"Indique le montant (minimum 2 $) puis appuie sur « Payer » : tu es redirigé vers la page de paiement sécurisée.":"Gib den Betrag an (mindestens 2 $) und tippe auf „Zahlen“: Du wirst zur sicheren Zahlungsseite weitergeleitet.",
