"Ton espace est protégé par ta connexion : seul le compte propriétaire y accède, vérifié côté serveur à chaque action.":"Dein Bereich ist durch deine Anmeldung geschützt: Nur das Inhaber-Konto hat Zugriff, bei jeder Aktion serverseitig geprüft.",
"Choisis un mot de passe long et unique et ne le partage jamais : l’équipe ne te le demandera jamais.":"Wähle ein langes, einzigartiges Passwort und teile es nie: Das Team fragt dich nie danach.",
