"Votre navigateur bloque l’enregistrement local. Sortez de la navigation privée et réessayez.":"Dein Browser blockiert das lokale Speichern. Verlasse den privaten Modus und versuche es erneut.",
"Voici, en 6 étapes simples, comment fonctionne un site créé ici. Lisez-les, puis touchez « Continuer ».":"Hier siehst du in 6 einfachen Schritten, wie eine hier erstellte Website funktioniert. Lies sie und tippe dann auf „Weiter“.",
"Vous choisissez le type de site":"Du wählst den Website-Typ",
"Boutique, restaurant, salon, école, agence… Vous remplissez le nom, les photos, les services et le contact. C’est gratuit, et l’aperçu montre exactement ce que verront vos clients, avant de payer quoi que ce soit.":"Shop, Restaurant, Salon, Schule, Agentur … Du gibst Name, Fotos, Dienstleistungen und Kontakt ein. Das ist kostenlos, und die Vorschau zeigt genau das, was deine Kunden sehen werden, bevor du irgendetwas bezahlst.",
"Vous activez le Pack Pro":"Du aktivierst das Pack Pro",
"Le Pack Pro ({0} $ par mois) met le site en ligne avec une vraie adresse, sans la marque Coeurnoh, avec des modèles et des couleurs au choix, les statistiques et la visibilité sur Google. Il se paie avec votre portefeuille.":"Das Pack Pro ({0} $ pro Monat) stellt die Website mit einer echten Adresse online, ohne die Coeurnoh-Marke, mit Vorlagen und Farben nach Wahl, Statistiken und Sichtbarkeit bei Google. Es wird mit deinem Wallet bezahlt.",
"Votre site a son adresse":"Deine Website hat ihre eigene Adresse",
"Dès la publication, il s’ouvre sur coeurnohuniverse.com/s/votre-nom, directement, sans écran de présentation. Vos clients peuvent l’installer sur l’écran d’accueil de leur téléphone.":"Ab der Veröffentlichung öffnet sie sich unter coeurnohuniverse.com/s/dein-name, direkt, ohne Vorschaubildschirm. Deine Kunden können sie auf dem Startbildschirm ihres Handys installieren.",
"Votre propre nom de domaine":"Dein eigener Domainname",
"Avec « Achat Domaine », vous achetez monentreprise.com avec votre portefeuille. Le site s’y connecte en un clic : le cadenas de sécurité et la redirection « www » sont gérés pour vous.":"Mit „Domain-Kauf“ kaufst du meinunternehmen.com mit deinem Wallet. Die Website verbindet sich mit einem Klick damit: Das Sicherheitsschloss und die „www“-Weiterleitung werden für dich erledigt.",
"Vos clients vous paient directement":"Deine Kunden bezahlen dich direkt",
"Dans « Mon espace », vous choisissez les passerelles de paiement de votre site (Mobile Money, carte bancaire…) ou le paiement à la livraison. L’argent va chez vous, et les commandes arrivent dans votre espace.":"In „Mein Bereich“ wählst du die Zahlungs-Gateways deiner Website (Mobile Money, Bankkarte …) oder die Zahlung bei Lieferung. Das Geld geht an dich, und die Bestellungen kommen in deinem Bereich an.",
"Google, WhatsApp et suivi":"Google, WhatsApp und Statistiken",
"Le site est prêt pour être trouvé sur Google (titre, description, plan du site) et partagé sur WhatsApp. Vous gérez commandes, messages, produits et statistiques depuis « Mon espace », en haut de votre site.":"Die Website ist bereit, auf Google gefunden (Titel, Beschreibung, Sitemap) und auf WhatsApp geteilt zu werden. Du verwaltest Bestellungen, Nachrichten, Produkte und Statistiken über „Mein Bereich“ oben auf deiner Website.",
