"Vous avez déjà un site. Ouvrez-le pour le modifier ou le publier.":"Du hast schon eine Website. Öffne sie, um sie zu bearbeiten oder zu veröffentlichen.",
"Créer le site pour un client":"Website für einen Kunden erstellen",
"Pour un client, un ami ou une entreprise. Je prépare tout, puis je lui remets seulement son e-mail et son mot de passe.":"Für einen Kunden, einen Freund oder ein Unternehmen. Ich bereite alles vor und übergebe ihm dann nur seine E-Mail und sein Passwort.",
"{0} projet(s) en préparation ou remis":"{0} Projekt(e) in Vorbereitung oder übergeben",
