"Vous écrivez le nom et l’e-mail de votre client.":"Du gibst den Namen und die E-Mail deines Kunden ein.",
"Un compte est créé au nom du client. Vous y entrez d’un seul bouton, sans mot de passe, et vous construisez son site.":"Auf den Namen des Kunden wird ein Konto erstellt. Du gelangst mit nur einem Button ohne Passwort hinein und baust seine Website.",
"Quand c’est prêt, vous touchez « Remettre au client » : il reçoit son e-mail et son mot de passe. Vous n’avez plus accès à son compte.":"Wenn alles fertig ist, tippst du auf „An Kunden übergeben“: Er erhält seine E-Mail und sein Passwort. Du hast dann keinen Zugriff mehr auf sein Konto.",
